import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] first = br.readLine().split(" ");
        int R = Integer.parseInt(first[0]);
        int N = Integer.parseInt(first[1]);

        int[] minPrice = new int[101];
        Arrays.fill(minPrice, Integer.MAX_VALUE);

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split(" ");
            int T = Integer.parseInt(parts[0]);
            int P = Integer.parseInt(parts[1]);
            if (P < minPrice[T]) {
                minPrice[T] = P;
            }
        }

        int[] prices = new int[N];
        int count = 0;

        for (int i = 1; i <= 100; i++) {
            if (minPrice[i] != Integer.MAX_VALUE) {
                prices[count++] = minPrice[i];
            }
        }

        Arrays.sort(prices, 0, count);

        int total = 0;
        int types = 0;

        for (int i = 0; i < count; i++) {
            if (total + prices[i] <= R) {
                total += prices[i];
                types++;
            } else {
                break;
            }
        }

        System.out.println(types);
    }
}
